(function() {
  $("form").submit(function(e) {
    var data, email;
    e.preventDefault();
    ga("send", "event", "Newsletter", "SubmitForm");
    email = $(".email").val();
    if (email === "") {
      alert(Lang.pleaseFillTheForm);
      return;
    }
    $(".submit").hide();
    $(".loading").removeClass("hidden");
    data = {
      email: email,
      lang: Lang.lang
    };
    return $.post("https://api.pioupiou.fr/v1/shop/newsletter", data, (function(response, textStatus) {
      console.log(response);
      if (response.error) {
        alert(Lang.errorRetry);
        return ga("send", "event", "Newsletter", "ErrorForm");
      } else {
        alert(Lang.successNewsletter + email);
        $(".email").val("");
        return ga("send", "event", "Newsletter", "Subscribe");
      }
    }), "json").error(function() {
      alert(Lang.errorRetry);
      return ga("send", "event", "Newsletter", "ErrorForm");
    }).always(function() {
      $(".submit").show();
      return $(".loading").addClass("hidden");
    });
  });

}).call(this);

